/**
 * E2E tests of the public timeline (B5): zoom anchoring, keyboard, pinch, RTL mirroring, deep
 * links and history. Runs the Vite dev server on port 51735 against the synthetic large data
 * set (scripts/make-large-dev-data.ts; generated by global-setup.ts when missing).
 *
 *   PLAYWRIGHT_BROWSERS_PATH=$PWD/.cache/ms-playwright pnpm --filter @omw/site e2e
 */
import { defineConfig, devices } from '@playwright/test';

const PORT = Number(process.env.OMW_E2E_PORT ?? 51735);
/**
 * OMW_E2E_MODE=preview runs the same specs against a production build (served by `vite preview`
 * from .cache/site-e2e-dist, so ./dist is never touched). Production builds serve the
 * pseudo-locale "ar" only when the manifest lists it, so the RTL specs fake such an RTL test
 * deployment there.
 */
const PREVIEW = process.env.OMW_E2E_MODE === 'preview';
const PREVIEW_DIR = '../../.cache/site-e2e-dist';

export default defineConfig({
  testDir: '.',
  // Only the timeline specs: other specs in this folder (the journey player's) have their own config.
  testMatch: /timeline.*\.spec\.ts$/,
  outputDir: '../../../.cache/playwright/site-results',
  globalSetup: './global-setup.ts',
  fullyParallel: true,
  workers: 3,
  retries: 0,
  timeout: 45_000,
  expect: { timeout: 7_000 },
  reporter: [['list']],
  use: {
    baseURL: `http://127.0.0.1:${PORT}`,
    trace: 'retain-on-failure',
    ...devices['Desktop Chrome'],
    viewport: { width: 1280, height: 900 },
  },
  webServer: {
    command: PREVIEW
      ? `pnpm exec vite build --outDir ${PREVIEW_DIR} --emptyOutDir && pnpm exec vite preview --outDir ${PREVIEW_DIR} --port ${PORT} --strictPort`
      : `pnpm exec vite --port ${PORT} --strictPort`,
    cwd: '..',
    env: { OMW_DEV_DATA_DIR: 'dev-data-large' },
    url: `http://127.0.0.1:${PORT}/de/`,
    // Never silently test a stray server (another checkout, an old build): reusing one is an
    // explicit choice (OMW_E2E_REUSE_SERVER=1, e.g. a dev server you keep running).
    reuseExistingServer: process.env.OMW_E2E_REUSE_SERVER === '1',
    timeout: PREVIEW ? 240_000 : 90_000,
  },
});
